#include <bits/stdc++.h>using namespace std;using ll = long long;const int mod = 1e9 + 7; struct Node{         vector<int> freq;         Node() : freq(26, 0) {}}; class SegTree{         int n;         vector<Node> seg; public:         SegTree(int n)         {                  this->n = n;                  seg.resize(4 * n);         }          Node merge(Node &left, Node &right)         {                  Node res;                   for (int i = 0; i < 26; i++)                  {                           res.freq[i] = left.freq[i] + right.freq[i];                  }                   return res;         }         void Build(int idx, int l, int r, string s)         {                  if (l == r)                  {                           seg[idx].freq[s[l] - 'a'] = 1;                           return;                  }                   int mid = (l + r) >> 1;                   Build(2 * idx + 1, l, mid, s);                  Build(2 * idx + 2, mid + 1, r, s);                   seg[idx] = merge(seg[2 * idx + 1], seg[2 * idx + 2]);         }          void Update(int idx, int l, int r, int pos, char c)         {                  if (l == r)                  {                           fill(seg[idx].freq.begin(), seg[idx].freq.end(), 0);                           seg[idx].freq[c - 'a'] = 1;                           return;                  }                   int mid = (l + r) >> 1;                   if (pos <= mid)                  {                           Update(2 * idx +   1, l, mid, pos, c);                  }                  else                  {                           Update(2 * idx + 2, mid + 1, r, pos, c);                  }                   seg[idx] = merge(seg[2 * idx + 1], seg[2 * idx + 2]);         }          Node Query(int idx, int l, int r, int left, int right)         {                  if (l > right || r < left)                  {                           return Node();                  }                   if (l >= left && r <= right)                  {                           return seg[idx];                  }                   int mid = (l + r) >> 1;                   Node L = Query(2 * idx + 1, l, mid, left, right);                  Node R = Query(2 * idx + 2, mid + 1, r, left, right);                   return merge(L, R);         }}; int32_t main(){         ios ::sync_with_stdio(false);         cin.tie(nullptr);          string s;         cin >> s;         int n = s.size();          SegTree *seg = new SegTree(n);          seg->Build(0, 0, n - 1, s);          int q;         cin >> q;          while (q--)         {                  int type;                  cin >> type;                   if (type == 1)                  {                           int pos;                           char ch;                           cin >> pos;                           cin >> ch;                           pos--;                           s[pos] = ch;                            seg->Update(0, 0, n - 1, pos, ch);                  }                  else                  {                           int left, right;                           cin >> left >> right;                            left--, right--;                            Node res = seg->Query(0, 0, n - 1, left, right);                            int dist = 0;                           for (auto it : res.freq)                           {                                    if (it > 0)                                    {                                             dist++;                                    }                           }                            cout << dist << endl;                  }         }          return 0;}